package com.secman.cli.service

import com.fasterxml.jackson.databind.ObjectMapper
import com.secman.crowdstrike.client.QueriedHost
import com.secman.crowdstrike.dto.CrowdStrikeVulnerabilityDto
import com.secman.crowdstrike.dto.resolveHostIps
import io.micronaut.context.annotation.Property
import io.micronaut.context.annotation.Value
import io.micronaut.http.HttpRequest
import io.micronaut.http.HttpResponse
import io.micronaut.http.client.HttpClient
import io.micronaut.http.client.annotation.Client
import jakarta.inject.Singleton
import org.slf4j.LoggerFactory
import java.time.LocalDateTime

/**
 * Service for storing vulnerabilities in secman database via backend API
 *
 * Functionality:
 * - POST vulnerabilities to backend API
 * - Handle deduplication
 * - Retry logic for transient failures
 * - Error recovery
 */
@Singleton
class VulnerabilityStorageService(
    @Client("\${secman.backend.base-url:http://localhost:8080}")
    private val httpClient: HttpClient,
    private val objectMapper: ObjectMapper,
    @Property(name = "secman.crowdstrike.max-vulnerabilities-per-batch", defaultValue = "50000")
    private val maxVulnerabilitiesPerBatch: Int,
    @Value("\${secman.crowdstrike.retry-backoff-base-ms:2000}")
    private val retryBackoffBaseMs: Long = 2000L,
    @Value("\${secman.crowdstrike.reconcile-poll-interval-ms:5000}")
    private val reconcilePollIntervalMs: Long = 5000L,
    @Value("\${secman.crowdstrike.reconcile-poll-timeout-ms:900000}")
    private val reconcilePollTimeoutMs: Long = 900000L
) {
    private val log = LoggerFactory.getLogger(VulnerabilityStorageService::class.java)

    /**
     * Authenticate with backend API and get JWT token
     *
     * @param username Backend username
     * @param password Backend password
     * @param backendUrl Backend API URL
     * @return JWT token or null if authentication failed
     */
    fun authenticate(username: String, password: String, backendUrl: String): String? {
        try {
            val endpoint = "/api/auth/login"
            val request = HttpRequest.POST(endpoint, mapOf(
                "username" to username,
                "password" to password
            )).contentType(io.micronaut.http.MediaType.APPLICATION_JSON)

            val response: HttpResponse<Map<*, *>> = httpClient.toBlocking()
                .exchange(request, Map::class.java)

            if (response.status.code == 200) {
                // JWT is in Set-Cookie header as "secman_auth=<token>; ..."
                val setCookieHeaders = response.headers.getAll("Set-Cookie")
                val token = setCookieHeaders
                    ?.flatMap { it.split(";") }
                    ?.firstOrNull { it.trim().startsWith("secman_auth=") }
                    ?.substringAfter("=")
                    ?.trim()

                if (token != null && token.isNotBlank()) {
                    log.info("Successfully authenticated with backend")
                    return token
                }

                // Fallback: try response body (for future API changes)
                val body = response.body()
                val bodyToken = body?.get("access_token")?.toString()
                    ?: body?.get("token")?.toString()
                    ?: body?.get("accessToken")?.toString()

                if (bodyToken != null) {
                    log.info("Successfully authenticated with backend (body token)")
                    return bodyToken
                }

                log.error("Authentication succeeded but no JWT found in Set-Cookie or response body")
            }

            log.error("Authentication failed: status={}", response.status)
            return null
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            when (e.status.code) {
                401, 403 -> log.error("Authentication failed: invalid credentials (HTTP {})", e.status.code)
                else -> log.error("Authentication HTTP error: {} - {}", e.status.code, e.message)
            }
            return null
        } catch (e: io.micronaut.discovery.exceptions.NoAvailableServiceException) {
            log.error("Cannot reach backend at '{}': {}", backendUrl, e.message)
            log.error("Check that SECMAN_BACKEND_URL or SECMAN_HOST includes the scheme (e.g. https://hostname)")
            return null
        } catch (e: java.net.ConnectException) {
            log.error("Connection refused to backend at '{}': {}", backendUrl, e.message)
            return null
        } catch (e: java.net.UnknownHostException) {
            log.error("DNS resolution failed for backend '{}': {}", backendUrl, e.message)
            return null
        } catch (e: javax.net.ssl.SSLHandshakeException) {
            log.error("SSL certificate verification failed for '{}': {}", backendUrl, e.message)
            log.error("If using a self-signed certificate, use --insecure flag or set SECMAN_INSECURE=true")
            return null
        } catch (e: javax.net.ssl.SSLException) {
            log.error("SSL error connecting to '{}': {}", backendUrl, e.message)
            return null
        } catch (e: io.micronaut.http.client.exceptions.ReadTimeoutException) {
            log.error("Connection to backend '{}' timed out", backendUrl)
            return null
        } catch (e: Exception) {
            val rootCause = generateSequence(e as Throwable?) { it.cause }.last()
            when (rootCause) {
                is java.net.ConnectException ->
                    log.error("Connection refused to backend at '{}': {}", backendUrl, rootCause.message)
                is java.net.UnknownHostException ->
                    log.error("DNS resolution failed for backend '{}': {}", backendUrl, rootCause.message)
                is javax.net.ssl.SSLException ->
                    log.error("SSL error connecting to '{}': {}", backendUrl, rootCause.message)
                else ->
                    log.error("Failed to connect to backend at '{}': {} ({})", backendUrl, e.message, e.javaClass.simpleName)
            }
            return null
        }
    }

    /**
     * Store vulnerabilities via backend API
     *
     * @param hostname System hostname
     * @param vulnerabilities List of vulnerabilities to store
     * @param backendUrl Optional backend URL override
     * @param authToken Optional JWT authentication token
     * @return StorageResult with statistics
     */
    fun storeVulnerabilities(
        hostname: String,
        vulnerabilities: List<CrowdStrikeVulnerabilityDto>,
        backendUrl: String? = null,
        authToken: String? = null
    ): StorageResult {
        if (vulnerabilities.isEmpty()) {
            log.debug("No vulnerabilities to store for {}", hostname)
            return StorageResult(stored = 0, skipped = 0, errors = emptyList())
        }

        log.info("Storing {} vulnerabilities for {} via backend API", vulnerabilities.size, hostname)

        try {
            // Build request payload
            val request = mapOf(
                "hostname" to hostname,
                "vulnerabilities" to vulnerabilities
            )

            // Use relative path so the @Client-configured base URL handles routing
            val endpoint = "/api/crowdstrike/vulnerabilities/save"

            // Make HTTP POST request with authentication
            val httpRequest = HttpRequest.POST(endpoint, request)
                .contentType(io.micronaut.http.MediaType.APPLICATION_JSON)

            // Add JWT token to Authorization header if provided
            if (authToken != null) {
                httpRequest.header("Authorization", "Bearer $authToken")
            }

            val response: HttpResponse<Map<*, *>> = httpClient.toBlocking()
                .exchange(httpRequest, Map::class.java)

            if (response.status.code == 200) {
                val body = response.body()
                val saved = (body?.get("vulnerabilitiesSaved") as? Number)?.toInt() ?: vulnerabilities.size
                val skipped = (body?.get("vulnerabilitiesSkipped") as? Number)?.toInt() ?: 0
                val assetsCreated = (body?.get("assetsCreated") as? Number)?.toInt() ?: 0
                val message = body?.get("message")?.toString() ?: "Saved successfully"

                log.info("Successfully stored vulnerabilities: saved={}, skipped={}, assetsCreated={}", saved, skipped, assetsCreated)
                return StorageResult(
                    stored = saved,
                    skipped = skipped,
                    errors = emptyList(),
                    assetsCreated = assetsCreated,
                    message = message
                )
            } else {
                val errorMsg = "Backend API returned status ${response.status.code}"
                log.error(errorMsg)
                return StorageResult(
                    stored = 0,
                    skipped = vulnerabilities.size,
                    errors = listOf(errorMsg)
                )
            }
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            val errorMsg = "Backend API error: ${e.status.code} - ${e.message}"
            log.error(errorMsg, e)

            // Implement retry logic for transient failures
            if (e.status.code in 500..599) {
                return retryStorage(hostname, vulnerabilities, backendUrl, retries = 2)
            }

            return StorageResult(
                stored = 0,
                skipped = vulnerabilities.size,
                errors = listOf(errorMsg)
            )
        } catch (e: Exception) {
            val errorMsg = "Failed to store vulnerabilities: ${e.message}"
            log.error(errorMsg, e)
            return StorageResult(
                stored = 0,
                skipped = vulnerabilities.size,
                errors = listOf(errorMsg)
            )
        }
    }

    /**
     * Retry storage operation with exponential backoff
     *
     * @param hostname System hostname
     * @param vulnerabilities List of vulnerabilities
     * @param backendUrl Backend URL
     * @param retries Number of retries remaining
     * @return StorageResult
     */
    private fun retryStorage(
        hostname: String,
        vulnerabilities: List<CrowdStrikeVulnerabilityDto>,
        backendUrl: String?,
        retries: Int
    ): StorageResult {
        if (retries <= 0) {
            log.error("Max retries exceeded for storing vulnerabilities")
            return StorageResult(
                stored = 0,
                skipped = vulnerabilities.size,
                errors = listOf("Max retries exceeded")
            )
        }

        val attempt = 3 - retries // 1 -> 2s, 2 -> 4s
        if (!sleepRetryBackoff(attempt)) {
            return StorageResult(
                stored = 0,
                skipped = vulnerabilities.size,
                errors = listOf("Retry interrupted")
            )
        }
        return storeVulnerabilities(hostname, vulnerabilities, backendUrl)
    }

    /**
     * Sleep for the shared retry backoff schedule (attempt is 1-based: 1 -> baseMs,
     * 2 -> 2*baseMs, ...). Used by both [retryStorage] (legacy single-host
     * `/vulnerabilities/save` path) and [sendBatchToBackend]'s gateway retry (batch
     * `/servers/import` path used by `--save`) so both retry loops share one place to
     * tune backoff timing. Returns false without sleeping if the thread is
     * interrupted, so callers can bail out cleanly instead of retrying after being
     * told to stop.
     */
    private fun sleepRetryBackoff(attempt: Int): Boolean {
        val backoffMs = attempt * retryBackoffBaseMs
        log.info("Retry backoff: sleeping {}ms before attempt {}", backoffMs, attempt + 1)
        return try {
            Thread.sleep(backoffMs)
            true
        } catch (e: InterruptedException) {
            Thread.currentThread().interrupt()
            log.error("Retry backoff interrupted", e)
            false
        }
    }

    /**
     * Store server vulnerabilities with metadata via backend batch import API
     *
     * This method implements chunking/batching to avoid 413 Request Entity Too Large errors
     * when processing large datasets (e.g., 94947 vulnerabilities across 857 servers).
     *
     * @param serverBatches Map of hostname to server data with metadata and vulnerabilities
     * @param backendUrl Optional backend URL override
     * @param authToken Optional JWT authentication token
     * @param batchSize Number of servers to process per batch (default 20, reduced from 50 to avoid 413 errors)
     * @return BatchStorageResult with aggregated statistics from all batches
     */
    fun storeServerVulnerabilities(
        serverBatches: Map<String, ServerVulnerabilityBatch>,
        backendUrl: String? = null,
        authToken: String? = null,
        batchSize: Int = 20,
        /**
         * Severities the whole run queried (e.g. ["CRITICAL","HIGH"]). Forwarded per
         * server so the backend's transactional replace deletes only CrowdStrike rows
         * at these severities instead of every row on the asset. Null (default) keeps
         * the backend's source-scoped fallback.
         */
        runSeverities: List<String>? = null
    ): BatchStorageResult {
        if (serverBatches.isEmpty()) {
            log.debug("No server vulnerabilities to store")
            return BatchStorageResult(
                serversProcessed = 0,
                serversCreated = 0,
                serversUpdated = 0,
                vulnerabilitiesImported = 0,
                vulnerabilitiesWithPatchDate = 0,
                vulnerabilitiesSkipped = 0,
                errors = emptyList()
            )
        }

        // Collapse Falcon's per-installation duplicates BEFORE any batching arithmetic, so
        // both the split thresholds and the posted payload count real findings. See
        // [dedupeByCveAndProduct] for why this cannot be left to the backend alone.
        val rawVulnCount = serverBatches.values.sumOf { it.vulnerabilities.size }
        val dedupedBatches = serverBatches.mapValues { (_, batch) ->
            batch.copy(vulnerabilities = dedupeByCveAndProduct(batch.vulnerabilities))
        }
        val dedupedVulnCount = dedupedBatches.values.sumOf { it.vulnerabilities.size }
        if (dedupedVulnCount < rawVulnCount) {
            log.info("Collapsed {} duplicate (CVE, product) row(s) across {} server(s) before send ({} -> {})",
                rawVulnCount - dedupedVulnCount, dedupedBatches.size, rawVulnCount, dedupedVulnCount)
        }

        val totalServers = dedupedBatches.size
        log.info("Storing vulnerabilities for {} servers via backend batch import API (batch size: {})", totalServers, batchSize)

        // Split servers into chunks to avoid 413 errors
        val serverChunks = dedupedBatches.entries.chunked(batchSize)
        val totalChunks = serverChunks.size

        log.info("Split into {} batches of up to {} servers each", totalChunks, batchSize)

        // Aggregate results across all batches (atomic to permit parallel POST)
        val totalServersProcessed = java.util.concurrent.atomic.AtomicInteger(0)
        val totalServersCreated = java.util.concurrent.atomic.AtomicInteger(0)
        val totalServersUpdated = java.util.concurrent.atomic.AtomicInteger(0)
        val totalVulnerabilitiesImported = java.util.concurrent.atomic.AtomicInteger(0)
        val totalVulnerabilitiesWithPatchDate = java.util.concurrent.atomic.AtomicInteger(0)
        val totalVulnerabilitiesSkipped = java.util.concurrent.atomic.AtomicInteger(0)
        val allErrors = java.util.concurrent.CopyOnWriteArrayList<String>()
        val allFailedHostnames = java.util.concurrent.CopyOnWriteArrayList<String>()

        // Parallelize backend POSTs across chunks. The backend's per-server @Transactional +
        // pessimistic write lock keep this safe: distinct hostnames never contend on the same
        // asset row. Pool size 3 = enough to overlap network + backend writes, small enough
        // that one slow asset doesn't snowball or exhaust HikariCP (maximum-pool-size: 20).
        val parallelism = minOf(3, totalChunks).coerceAtLeast(1)
        val executor = java.util.concurrent.Executors.newFixedThreadPool(parallelism) { r ->
            Thread(r, "crowdstrike-post-worker").apply { isDaemon = false }
        }
        try {
            val futures = serverChunks.mapIndexed { index, chunk ->
                executor.submit<Unit> {
                    val chunkNumber = index + 1
                    val chunkSize = chunk.size

                    log.info("Importing batch {}/{} ({} servers)...", chunkNumber, totalChunks, chunkSize)
                    println("Importing batch $chunkNumber/$totalChunks ($chunkSize servers)...")

                    val chunkMap = chunk.associate { it.key to it.value }
                    try {
                        val chunkResult = processSingleBatch(chunkMap, backendUrl, authToken, runSeverities)

                        totalServersProcessed.addAndGet(chunkResult.serversProcessed)
                        totalServersCreated.addAndGet(chunkResult.serversCreated)
                        totalServersUpdated.addAndGet(chunkResult.serversUpdated)
                        totalVulnerabilitiesImported.addAndGet(chunkResult.vulnerabilitiesImported)
                        totalVulnerabilitiesWithPatchDate.addAndGet(chunkResult.vulnerabilitiesWithPatchDate)
                        totalVulnerabilitiesSkipped.addAndGet(chunkResult.vulnerabilitiesSkipped)
                        allErrors.addAll(chunkResult.errors)
                        allFailedHostnames.addAll(chunkResult.failedHostnames)

                        log.info("Batch {}/{} completed: processed={}, created={}, updated={}, imported={}, skipped={}, failedHosts={}",
                            chunkNumber, totalChunks, chunkResult.serversProcessed, chunkResult.serversCreated,
                            chunkResult.serversUpdated, chunkResult.vulnerabilitiesImported, chunkResult.vulnerabilitiesSkipped,
                            chunkResult.failedHostnames.size)
                    } catch (e: Exception) {
                        val errorMsg = "Failed to process batch $chunkNumber/$totalChunks: ${e.message}"
                        log.error(errorMsg, e)
                        allErrors.add(errorMsg)
                        // Whole chunk failed to persist — every host in it must be kept
                        // out of the reconcile sweep's scope.
                        allFailedHostnames.addAll(chunkMap.keys)
                    }
                }
            }
            // Drain all futures so any uncaught Future exceptions surface here, not silently.
            futures.forEach { f ->
                try { f.get() } catch (e: Exception) {
                    log.error("Unexpected error from POST worker future", e)
                    allErrors.add("Unexpected POST worker error: ${e.message}")
                }
            }
        } finally {
            executor.shutdown()
            if (!executor.awaitTermination(60, java.util.concurrent.TimeUnit.SECONDS)) {
                executor.shutdownNow()
            }
        }

        val processedFinal = totalServersProcessed.get()
        val createdFinal = totalServersCreated.get()
        val updatedFinal = totalServersUpdated.get()
        val importedFinal = totalVulnerabilitiesImported.get()
        val withPatchFinal = totalVulnerabilitiesWithPatchDate.get()
        val skippedFinal = totalVulnerabilitiesSkipped.get()
        val errorsFinal = allErrors.toList()

        log.info("All batches completed: total servers processed={}, created={}, updated={}, vulnerabilities imported={}, skipped={}, errors={}",
            processedFinal, createdFinal, updatedFinal,
            importedFinal, skippedFinal, errorsFinal.size)

        println("\nImport Summary:")
        println("  Servers processed: $processedFinal")
        println("  Servers created: $createdFinal")
        println("  Servers updated: $updatedFinal")
        println("  Vulnerabilities imported: $importedFinal")
        println("  Vulnerabilities skipped: $skippedFinal")
        if (errorsFinal.isNotEmpty()) {
            println("  Errors: ${errorsFinal.size}")
        }

        return BatchStorageResult(
            serversProcessed = processedFinal,
            serversCreated = createdFinal,
            serversUpdated = updatedFinal,
            vulnerabilitiesImported = importedFinal,
            vulnerabilitiesWithPatchDate = withPatchFinal,
            vulnerabilitiesSkipped = skippedFinal,
            errors = errorsFinal,
            failedHostnames = allFailedHostnames.distinct()
        )
    }

    /**
     * Process a single batch of servers via backend import API
     *
     * This is a helper method extracted from storeServerVulnerabilities to enable batching.
     * If the batch contains too many vulnerabilities, it will be split into sub-batches
     * to avoid 413 Request Entity Too Large errors.
     *
     * @param serverBatch Map of hostname to server data for this batch
     * @param backendUrl Optional backend URL override
     * @param authToken Optional JWT authentication token
     * @return BatchStorageResult for this single batch
     */
    private fun processSingleBatch(
        serverBatch: Map<String, ServerVulnerabilityBatch>,
        backendUrl: String?,
        authToken: String?,
        runSeverities: List<String>? = null
    ): BatchStorageResult {
        // Check total vulnerability count and split if needed to avoid 413 errors
        val totalVulns = serverBatch.values.sumOf { it.vulnerabilities.size }
        if (totalVulns > maxVulnerabilitiesPerBatch && serverBatch.size > 1) {
            log.info("Batch has {} vulnerabilities (limit: {}), splitting into sub-batches",
                totalVulns, maxVulnerabilitiesPerBatch)
            return splitAndProcessBatch(serverBatch, backendUrl, authToken, runSeverities)
        }

        // Delegate to sendBatchToBackend for actual HTTP request
        return sendBatchToBackend(serverBatch, backendUrl, authToken, runSeverities = runSeverities)
    }

    /**
     * Split a batch by vulnerability count to avoid 413 Request Entity Too Large errors
     *
     * This method is called when a batch has too many vulnerabilities. It splits the batch
     * into smaller sub-batches based on vulnerability count rather than server count,
     * then processes each sub-batch and aggregates the results.
     *
     * @param serverBatch Map of hostname to server data for this batch
     * @param backendUrl Optional backend URL override
     * @param authToken Optional JWT authentication token
     * @return BatchStorageResult with aggregated results from all sub-batches
     */
    private fun splitAndProcessBatch(
        serverBatch: Map<String, ServerVulnerabilityBatch>,
        backendUrl: String?,
        authToken: String?,
        runSeverities: List<String>? = null
    ): BatchStorageResult {
        // Sort servers by vulnerability count (process smaller ones first to maximize batching)
        val sortedServers = serverBatch.entries.sortedBy { it.value.vulnerabilities.size }

        var currentBatch = mutableMapOf<String, ServerVulnerabilityBatch>()
        var currentVulnCount = 0
        val subBatchResults = mutableListOf<BatchStorageResult>()
        var subBatchNumber = 0

        for (entry in sortedServers) {
            val serverVulnCount = entry.value.vulnerabilities.size

            // If adding this server would exceed limit, process current batch first
            if (currentVulnCount + serverVulnCount > maxVulnerabilitiesPerBatch && currentBatch.isNotEmpty()) {
                subBatchNumber++
                log.info("Processing sub-batch {} with {} servers, {} vulnerabilities",
                    subBatchNumber, currentBatch.size, currentVulnCount)
                println("  Sub-batch $subBatchNumber: ${currentBatch.size} servers, $currentVulnCount vulnerabilities")

                // Send this sub-batch directly to backend (bypass processSingleBatch to avoid infinite recursion)
                subBatchResults.add(sendBatchToBackend(currentBatch.toMap(), backendUrl, authToken, runSeverities = runSeverities))
                currentBatch = mutableMapOf()
                currentVulnCount = 0
            }

            currentBatch[entry.key] = entry.value
            currentVulnCount += serverVulnCount
        }

        // Process remaining servers
        if (currentBatch.isNotEmpty()) {
            subBatchNumber++
            log.info("Processing final sub-batch {} with {} servers, {} vulnerabilities",
                subBatchNumber, currentBatch.size, currentVulnCount)
            println("  Sub-batch $subBatchNumber: ${currentBatch.size} servers, $currentVulnCount vulnerabilities")
            subBatchResults.add(sendBatchToBackend(currentBatch.toMap(), backendUrl, authToken, runSeverities = runSeverities))
        }

        // Aggregate all sub-batch results
        return aggregateResults(subBatchResults)
    }

    /**
     * Send a batch to the backend API, retrying on transient gateway failures.
     *
     * Wraps [sendBatchToBackendOnce] in a small retry loop for exactly the failure
     * modes that are safe and worth retrying: 502/503/504 and client-side read
     * timeouts. Retrying is safe because the backend replaces (delete+insert) each
     * hostname's vulnerabilities in one transaction per server
     * (CrowdStrikeVulnerabilityImportService "Duplicate Prevention Strategy") — a
     * re-sent batch converges to the same end state. All other failures (4xx other
     * than these, unexpected exceptions) are not retried, matching prior behavior.
     *
     * 2026-07-21 incident: a transient 504 during a long CrowdStrike import used to
     * permanently drop that sub-batch's vulnerabilities with no retry.
     */
    private fun sendBatchToBackend(
        serverBatch: Map<String, ServerVulnerabilityBatch>,
        backendUrl: String?,
        authToken: String?,
        retriesRemaining: Int = MAX_GATEWAY_RETRIES,
        runSeverities: List<String>? = null
    ): BatchStorageResult {
        return try {
            sendBatchToBackendOnce(serverBatch, backendUrl, authToken, runSeverities)
        } catch (e: RetryableGatewayException) {
            val totalVulns = serverBatch.values.sumOf { it.vulnerabilities.size }
            if (retriesRemaining <= 0) {
                val errorMsg = "Backend API error: ${e.statusLabel} after $MAX_GATEWAY_RETRIES retries " +
                    "(servers=${serverBatch.size}, vulns=$totalVulns) - ${e.cause?.message}"
                log.error(errorMsg, e.cause)
                return BatchStorageResult(
                    serversProcessed = 0,
                    serversCreated = 0,
                    serversUpdated = 0,
                    vulnerabilitiesImported = 0,
                    vulnerabilitiesWithPatchDate = 0,
                    vulnerabilitiesSkipped = 0,
                    errors = listOf(errorMsg),
                    failedHostnames = serverBatch.keys.toList()
                )
            }
            val attempt = MAX_GATEWAY_RETRIES - retriesRemaining + 1
            log.warn("Retryable gateway failure ({}) sending batch of {} servers / {} vulns — retrying (attempt {}/{})",
                e.statusLabel, serverBatch.size, totalVulns, attempt, MAX_GATEWAY_RETRIES)
            if (!sleepRetryBackoff(attempt)) {
                return BatchStorageResult(
                    serversProcessed = 0,
                    serversCreated = 0,
                    serversUpdated = 0,
                    vulnerabilitiesImported = 0,
                    vulnerabilitiesWithPatchDate = 0,
                    vulnerabilitiesSkipped = 0,
                    errors = listOf("Retry interrupted after ${e.statusLabel}"),
                    failedHostnames = serverBatch.keys.toList()
                )
            }
            sendBatchToBackend(serverBatch, backendUrl, authToken, retriesRemaining - 1, runSeverities)
        }
    }

    private companion object {
        val RETRYABLE_HTTP_STATUSES = setOf(502, 503, 504)
        const val MAX_GATEWAY_RETRIES = 2 // mirrors retryStorage's default of 2 retries
    }

    /**
     * Thrown by [sendBatchToBackendOnce] for failures worth retrying: 502/503/504
     * gateway responses and client-side read timeouts. Both are consistent with a
     * transient upstream/proxy hiccup rather than a data problem.
     */
    private class RetryableGatewayException(val statusLabel: String, cause: Throwable) :
        Exception("Retryable gateway failure: $statusLabel", cause)

    /**
     * Send a batch directly to the backend API — one attempt, no retry (extracted
     * from processSingleBatch). Used by both processSingleBatch and
     * splitAndProcessBatch via the retrying wrapper [sendBatchToBackend].
     *
     * @param serverBatch Map of hostname to server data for this batch
     * @param backendUrl Optional backend URL override
     * @param authToken Optional JWT authentication token
     * @return BatchStorageResult for this single batch
     */
    private fun sendBatchToBackendOnce(
        serverBatch: Map<String, ServerVulnerabilityBatch>,
        backendUrl: String?,
        authToken: String?,
        runSeverities: List<String>? = null
    ): BatchStorageResult {
        try {
            // Validate and sanitize batch data before sending
            val totalVulns = serverBatch.values.sumOf { it.vulnerabilities.size }
            log.info("Sending batch with {} servers, {} vulnerabilities to backend", serverBatch.size, totalVulns)

            val validatedBatch = serverBatch.mapNotNull { (hostname, batch) ->
                // Validate hostname
                if (hostname.isBlank()) {
                    log.warn("Skipping server with blank hostname")
                    return@mapNotNull null
                }
                if (hostname.length > 255) {
                    log.warn("Skipping server with hostname too long: '{}' ({} chars)", hostname.take(50), hostname.length)
                    return@mapNotNull null
                }

                // Validate and filter vulnerabilities
                val validVulns = batch.vulnerabilities.filter { vuln ->
                    val cveId = vuln.cveId
                    if (cveId.isNullOrBlank()) {
                        log.warn("Skipping vulnerability with blank CVE ID for server '{}'", hostname)
                        return@filter false
                    }
                    if (cveId.length > 255) {
                        log.warn("Skipping vulnerability with CVE ID too long for server '{}': {} chars", hostname, cveId.length)
                        return@filter false
                    }
                    val severity = vuln.severity
                    if (severity.isNullOrBlank()) {
                        log.warn("Skipping vulnerability {} for server '{}': severity is blank", cveId, hostname)
                        return@filter false
                    }
                    if (severity.length > 50) {
                        log.warn("Skipping vulnerability {} for server '{}': severity too long ({} chars)", cveId, hostname, severity.length)
                        return@filter false
                    }
                    true
                }

                if (validVulns.isEmpty()) {
                    log.warn("Skipping server '{}': all {} vulnerabilities were invalid", hostname, batch.vulnerabilities.size)
                    return@mapNotNull null
                }

                hostname to batch.copy(vulnerabilities = validVulns)
            }.toMap()

            if (validatedBatch.isEmpty()) {
                log.error("All servers in batch were invalid - no data to send")
                return BatchStorageResult(
                    serversProcessed = 0,
                    serversCreated = 0,
                    serversUpdated = 0,
                    vulnerabilitiesImported = 0,
                    vulnerabilitiesWithPatchDate = 0,
                    vulnerabilitiesSkipped = serverBatch.values.sumOf { it.vulnerabilities.size },
                    errors = listOf("All servers in batch failed validation"),
                    failedHostnames = serverBatch.keys.toList()
                )
            }

            // Servers dropped by client-side validation were never sent: their old rows
            // stay un-refreshed, so they must be excluded from the reconcile sweep too.
            val droppedHosts = serverBatch.keys - validatedBatch.keys

            // Convert to backend DTO format. runSeverities tells the backend to scope its
            // transactional replace to this run's severity slice (source=CROWDSTRIKE only)
            // instead of wiping every row on the asset.
            val serverBatchDtos = validatedBatch.map { (hostname, batch) ->
                mapOf(
                    "hostname" to hostname,
                    "groups" to batch.groups,
                    "cloudAccountId" to batch.cloudAccountId,
                    "cloudInstanceId" to batch.cloudInstanceId,
                    "adDomain" to batch.adDomain,
                    "osVersion" to batch.osVersion,
                    "ip" to batch.ip,
                    "ipAddresses" to batch.vulnerabilities.resolveHostIps(),
                    "crowdStrikeAids" to batch.vulnerabilities
                        .mapNotNull { it.crowdStrikeAid?.takeIf(String::isNotBlank) }
                        .distinct(),
                    "runSeverities" to runSeverities,
                    "vulnerabilities" to batch.vulnerabilities.map { vuln ->
                        // Dates travel as ISO-8601 strings rather than being re-derived
                        // backend-side from `daysOpen`. That round-trip (precise instant ->
                        // whole-day integer -> backendNow minus N) truncated twice and
                        // crossed two clocks, and it silently discarded both publication
                        // dates — which is why use-patch-publication-date could never take
                        // effect on this, the high-volume batch path. `daysOpen` is still
                        // sent so an older backend keeps working.
                        mapOf(
                            "cveId" to vuln.cveId,
                            "severity" to vuln.severity,
                            "affectedProduct" to vuln.affectedProduct?.take(512),
                            "daysOpen" to parseDaysOpenToInt(vuln.daysOpen),
                            "detectedAt" to vuln.detectedAt?.toString(),
                            "patchPublicationDate" to vuln.patchPublicationDate?.toString(),
                            "cvePublishedDate" to vuln.cvePublishedDate?.toString()
                        )
                    }
                )
            }

            // Use relative path so the @Client-configured base URL handles routing
            // (connects through nginx on HTTPS instead of bypassing to localhost:8080)
            val endpoint = "/api/crowdstrike/servers/import"

            // Make HTTP POST request with optional authentication
            val httpRequest = HttpRequest.POST(endpoint, serverBatchDtos)
                .contentType(io.micronaut.http.MediaType.APPLICATION_JSON)

            if (authToken != null) {
                httpRequest.header("Authorization", "Bearer $authToken")
            }

            val response: HttpResponse<Map<*, *>> = httpClient.toBlocking()
                .exchange(httpRequest, Map::class.java)

            if (response.status.code == 200) {
                val body = response.body()

                val serversProcessed = (body?.get("serversProcessed") as? Number)?.toInt() ?: serverBatch.size
                val serversCreated = (body?.get("serversCreated") as? Number)?.toInt() ?: 0
                val serversUpdated = (body?.get("serversUpdated") as? Number)?.toInt() ?: 0
                val vulnerabilitiesImported = (body?.get("vulnerabilitiesImported") as? Number)?.toInt() ?: 0
                val vulnerabilitiesWithPatchDate = (body?.get("vulnerabilitiesWithPatchDate") as? Number)?.toInt() ?: 0
                val vulnerabilitiesSkipped = (body?.get("vulnerabilitiesSkipped") as? Number)?.toInt() ?: 0
                @Suppress("UNCHECKED_CAST")
                val errors = (body?.get("errors") as? List<String>) ?: emptyList()
                // Servers whose per-server import transaction rolled back on the backend:
                // their old rows survived un-refreshed and must not be swept as stale.
                val backendFailedHostnames = (body?.get("failedHostnames") as? List<*>)
                    ?.map { it.toString() } ?: emptyList()

                return BatchStorageResult(
                    serversProcessed = serversProcessed,
                    serversCreated = serversCreated,
                    serversUpdated = serversUpdated,
                    vulnerabilitiesImported = vulnerabilitiesImported,
                    vulnerabilitiesWithPatchDate = vulnerabilitiesWithPatchDate,
                    vulnerabilitiesSkipped = vulnerabilitiesSkipped,
                    errors = errors,
                    failedHostnames = (backendFailedHostnames + droppedHosts).distinct()
                )
            } else {
                val errorMsg = "Backend API returned status ${response.status.code}"
                log.error(errorMsg)
                return BatchStorageResult(
                    serversProcessed = 0,
                    serversCreated = 0,
                    serversUpdated = 0,
                    vulnerabilitiesImported = 0,
                    vulnerabilitiesWithPatchDate = 0,
                    vulnerabilitiesSkipped = 0,
                    errors = listOf(errorMsg),
                    failedHostnames = serverBatch.keys.toList()
                )
            }
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            if (e.status.code in RETRYABLE_HTTP_STATUSES) {
                throw RetryableGatewayException("HTTP ${e.status.code}", e)
            }
            // Try to parse structured JSON error body
            val responseBody = try {
                e.response.getBody(Map::class.java).orElse(null)
            } catch (ex: Exception) {
                null
            }

            // Try to read raw response body as string (useful for proxy error pages)
            val rawBody = if (responseBody == null) {
                try {
                    e.response.getBody(String::class.java).orElse(null)
                } catch (ex: Exception) {
                    null
                }
            } else null

            val violations = responseBody?.get("violations") as? List<*>
            val detailedErrors = violations?.joinToString("; ") { it.toString() }

            val errorMsg = if (detailedErrors != null) {
                "Backend API error: ${e.status.code} - Validation failed: $detailedErrors"
            } else if (responseBody != null) {
                val errorDetail = responseBody["error"] ?: responseBody["message"] ?: e.message
                "Backend API error: ${e.status.code} - $errorDetail"
            } else {
                val bodySnippet = rawBody?.take(500)?.let { " | Response body: $it" } ?: ""
                "Backend API error: ${e.status.code} - ${e.message}$bodySnippet"
            }

            val isNginxError = rawBody?.contains("nginx") == true || rawBody?.contains("<html>") == true
            if (isNginxError) {
                log.error("Received nginx/proxy error page instead of backend JSON response (HTTP {}). " +
                    "The request likely did not reach the backend application. " +
                    "Check: (1) backend is running on the expected port, " +
                    "(2) nginx proxy_pass and proxy_intercept_errors settings, " +
                    "(3) backend startup logs for bean creation errors on the target controller",
                    e.status.code)
            }

            log.error("Backend HTTP error: status={}, reason={}, exception={}, responseBody={}",
                e.status.code, e.status.reason, e.javaClass.simpleName,
                responseBody ?: rawBody?.take(500) ?: "<empty>", e)
            return BatchStorageResult(
                serversProcessed = 0,
                serversCreated = 0,
                serversUpdated = 0,
                vulnerabilitiesImported = 0,
                vulnerabilitiesWithPatchDate = 0,
                vulnerabilitiesSkipped = 0,
                errors = listOf(errorMsg),
                failedHostnames = serverBatch.keys.toList()
            )
        } catch (e: io.micronaut.http.client.exceptions.ReadTimeoutException) {
            throw RetryableGatewayException("ReadTimeout", e)
        } catch (e: RetryableGatewayException) {
            // Must be re-thrown before the generic catch below, or it would be
            // swallowed into a BatchStorageResult here instead of propagating to
            // sendBatchToBackend()'s retry loop.
            throw e
        } catch (e: Exception) {
            val errorMsg = "Failed to send batch to backend: [${e.javaClass.simpleName}] ${e.message}"
            log.error("Unexpected error sending batch to backend: exceptionType={}, message={}",
                e.javaClass.name, e.message, e)
            return BatchStorageResult(
                serversProcessed = 0,
                serversCreated = 0,
                serversUpdated = 0,
                vulnerabilitiesImported = 0,
                vulnerabilitiesWithPatchDate = 0,
                vulnerabilitiesSkipped = 0,
                errors = listOf(errorMsg),
                failedHostnames = serverBatch.keys.toList()
            )
        }
    }

    /**
     * Aggregate results from multiple sub-batches into a single result
     *
     * @param results List of BatchStorageResult from sub-batches
     * @return Aggregated BatchStorageResult
     */
    private fun aggregateResults(results: List<BatchStorageResult>): BatchStorageResult {
        return BatchStorageResult(
            serversProcessed = results.sumOf { it.serversProcessed },
            serversCreated = results.sumOf { it.serversCreated },
            serversUpdated = results.sumOf { it.serversUpdated },
            vulnerabilitiesImported = results.sumOf { it.vulnerabilitiesImported },
            vulnerabilitiesWithPatchDate = results.sumOf { it.vulnerabilitiesWithPatchDate },
            vulnerabilitiesSkipped = results.sumOf { it.vulnerabilitiesSkipped },
            errors = results.flatMap { it.errors },
            failedHostnames = results.flatMap { it.failedHostnames }.distinct()
        )
    }

    /**
     * Parse daysOpen string to integer value
     *
     * Handles formats:
     * - "526 days" -> 526
     * - "1 day" -> 1
     * - "0 days" -> 0
     * - null or invalid -> 0
     *
     * @param daysOpen String in format "X days" or "X day"
     * @return Integer value of days
     */
    /**
     * Collapse duplicate (CVE, affected product) rows for one host before batching.
     *
     * Falcon reports one record per *installed instance* of a product, so a host with a
     * handful of products spread over many paths/versions returns far more rows than it
     * has distinct findings: one observed host sent 66,946 rows carrying only 2,458
     * distinct (CVE, product) pairs across 11 products — 96% duplicates.
     *
     * The backend already collapses these with this exact key in
     * `CrowdStrikeVulnerabilityImportService.importVulnerabilitiesForServer`, but only
     * *after* bean validation. Any host above the 50,000-row cap on
     * `CrowdStrikeVulnerabilityBatchDto.vulnerabilities` was therefore rejected with 400
     * and dropped in full, every run — and it could not be rescued by splitting, because
     * splitting is per server and the backend's per-host import is a transactional
     * delete-then-insert replace: sending one host across two requests would make the
     * second request delete what the first inserted.
     *
     * Deduplicating here is behaviour-preserving — same key, same "highest daysOpen wins"
     * tie-break as the backend — and keeps the cap a meaningful memory guard instead of
     * forcing it upward. `affectedProduct` is truncated to the same 512 chars the payload
     * is truncated to below, so the key matches what the backend actually receives.
     */
    private fun dedupeByCveAndProduct(
        vulnerabilities: List<CrowdStrikeVulnerabilityDto>
    ): List<CrowdStrikeVulnerabilityDto> =
        vulnerabilities
            .groupBy { Pair(it.cveId, it.affectedProduct?.take(512)) }
            .map { (_, duplicates) ->
                duplicates.maxByOrNull { parseDaysOpenToInt(it.daysOpen) } ?: duplicates.first()
            }

    private fun parseDaysOpenToInt(daysOpen: String?): Int {
        if (daysOpen.isNullOrBlank()) {
            return 0
        }

        return try {
            // Extract numeric part from "526 days" or "1 day"
            daysOpen.split(" ").firstOrNull()?.toIntOrNull() ?: 0
        } catch (e: Exception) {
            log.warn("Failed to parse daysOpen '{}': {}", daysOpen, e.message)
            0
        }
    }

    /**
     * After a streaming `--save` import completes, ask the backend to delete
     * CrowdStrike-import-owned vulnerability rows that the run did NOT re-stamp.
     *
     * Such rows belong to hosts that no longer match the importer's filter (either
     * remediated below `--severity` or absent under `--last-seen-days`), so leaving
     * them would surface stale findings indefinitely in the lookup UI.
     *
     * Returns `null` only when [severities] is empty (no-op, not a failure).
     * On HTTP or transport errors throws [ReconcileFailedException] — the caller
     * MUST surface that as a non-zero exit, since silently leaving stale rows
     * defeats the purpose of running reconcile in the first place.
     *
     * The backend runs the sweep as a background job (a synchronous sweep exceeded
     * nginx's 60s proxy timeout on large tables → 504 even though the backend
     * completed fine). The POST returns 202 + jobId immediately; this method then
     * polls the status endpoint every [reconcilePollIntervalMs] until the job reaches
     * a terminal status or [reconcilePollTimeoutMs] elapses.
     */
    @Throws(ReconcileFailedException::class)
    fun reconcileStaleVulnerabilities(
        importStartedAt: LocalDateTime,
        severities: List<String>,
        queriedHosts: Set<QueriedHost> = emptySet(),
        backendUrl: String? = null,
        authToken: String? = null,
        dryRun: Boolean = false,
        excludedFailedHostCount: Int? = null
    ): ReconcileStaleResult? {
        if (severities.isEmpty()) {
            log.debug("No severities supplied for reconciliation, skipping")
            return null
        }

        val endpoint = "/api/crowdstrike/servers/reconcile-stale"
        // queriedHosts scopes the backend sweep to hosts this run actually queried, so a
        // host outside --last-seen-days is never wiped. An empty set makes the backend
        // delete nothing (fail-safe).
        //
        // clientNow lets the backend measure this machine's clock offset and translate
        // importStartedAt into its own clock. Without it, a TZ mismatch makes the cutoff
        // meaningless — the 2026-08-21 incident deleted 727,637 just-imported rows when
        // the backend's old 30-minute fallback landed inside a >1h import run.
        val body = mapOf(
            "importStartedAt" to importStartedAt.toString(),
            "severities" to severities,
            "queriedHosts" to queriedHosts.map {
                mapOf(
                    "hostname" to it.hostname,
                    "instanceId" to it.instanceId,
                    "crowdStrikeAid" to it.crowdStrikeAid
                )
            },
            "clientNow" to LocalDateTime.now().toString(),
            "dryRun" to dryRun,
            "excludedFailedHostCount" to excludedFailedHostCount
        )

        val jobId = startReconcileJob(endpoint, body, authToken)
        log.info(
            "Reconcile job started (id={}), polling every {}ms (timeout {}s)",
            jobId, reconcilePollIntervalMs, reconcilePollTimeoutMs / 1000
        )
        return pollReconcileJob(endpoint, jobId, authToken, importStartedAt, severities)
    }

    /**
     * POST the reconcile request and return the backend's jobId. Expects 202.
     *
     * Retries the POST once on a transient gateway status (502/503/504) — safe
     * because the backend's single-job guard turns a duplicate start into a 409.
     * A 409 always fails hard: either another run's reconcile is in flight (cron
     * overlap) or our own first attempt started a job whose response was lost;
     * both cases exit 2 with the "may persist" warning so operators re-run.
     */
    private fun startReconcileJob(endpoint: String, body: Map<String, Any?>, authToken: String?): String {
        var attempt = 0
        while (true) {
            try {
                val httpRequest = HttpRequest.POST(endpoint, body)
                    .contentType(io.micronaut.http.MediaType.APPLICATION_JSON)
                if (authToken != null) {
                    httpRequest.header("Authorization", "Bearer $authToken")
                }

                val response: HttpResponse<Map<*, *>> = httpClient.toBlocking()
                    .exchange(httpRequest, Map::class.java)

                if (response.status.code != 202) {
                    throw ReconcileFailedException(
                        "Reconcile endpoint returned HTTP ${response.status.code} (expected 202)"
                    )
                }
                val jobId = response.body()?.get("jobId")?.toString()
                if (jobId.isNullOrBlank()) {
                    throw ReconcileFailedException("Reconcile endpoint returned no jobId")
                }
                return jobId
            } catch (e: ReconcileFailedException) {
                throw e
            } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
                when {
                    e.status.code == 409 -> {
                        val runningJobId = e.response.getBody(Map::class.java).orElse(null)?.get("jobId")
                        throw ReconcileFailedException(
                            "A reconcile job is already running on the backend (jobId=$runningJobId)", e
                        )
                    }
                    e.status.code in RETRYABLE_HTTP_STATUSES && attempt == 0 -> {
                        attempt++
                        log.warn("Reconcile start returned HTTP {}, retrying once", e.status.code)
                        if (!sleepRetryBackoff(attempt)) {
                            throw ReconcileFailedException("Reconcile start retry interrupted", e)
                        }
                    }
                    else -> throw ReconcileFailedException(
                        "Reconcile call failed: HTTP ${e.status.code} - ${e.message}", e
                    )
                }
            } catch (e: Exception) {
                throw ReconcileFailedException("Reconcile call error: ${e.message}", e)
            }
        }
    }

    /**
     * Poll GET {endpoint}/{jobId}/status until COMPLETED (returns the parsed result),
     * FAILED (throws), or the overall deadline passes (throws). Up to 3 consecutive
     * transient poll errors are tolerated before giving up; a 404 fails immediately
     * (job unknown to the backend — nothing further to wait for).
     */
    private fun pollReconcileJob(
        endpoint: String,
        jobId: String,
        authToken: String?,
        importStartedAt: LocalDateTime,
        severities: List<String>
    ): ReconcileStaleResult {
        val statusEndpoint = "$endpoint/$jobId/status"
        val deadline = System.currentTimeMillis() + reconcilePollTimeoutMs
        var consecutiveFailures = 0

        while (true) {
            if (System.currentTimeMillis() >= deadline) {
                throw ReconcileFailedException(
                    "Reconcile job $jobId did not finish within ${reconcilePollTimeoutMs / 1000}s"
                )
            }
            try {
                Thread.sleep(reconcilePollIntervalMs)
            } catch (e: InterruptedException) {
                Thread.currentThread().interrupt()
                throw ReconcileFailedException("Reconcile status polling interrupted", e)
            }

            val statusBody = try {
                val httpRequest = HttpRequest.GET<Any>(statusEndpoint)
                if (authToken != null) {
                    httpRequest.header("Authorization", "Bearer $authToken")
                }
                val response: HttpResponse<Map<*, *>> = httpClient.toBlocking()
                    .exchange(httpRequest, Map::class.java)
                response.body()
                    ?: throw ReconcileFailedException("Reconcile status endpoint returned empty body")
            } catch (e: ReconcileFailedException) {
                throw e
            } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
                if (e.status.code == 404) {
                    throw ReconcileFailedException("Reconcile job $jobId not found on backend", e)
                }
                if (++consecutiveFailures > 3) {
                    throw ReconcileFailedException(
                        "Reconcile status polling failed ${consecutiveFailures} times in a row: HTTP ${e.status.code}", e
                    )
                }
                log.warn("Transient reconcile status poll failure ({}/3): HTTP {}", consecutiveFailures, e.status.code)
                continue
            } catch (e: Exception) {
                if (++consecutiveFailures > 3) {
                    throw ReconcileFailedException(
                        "Reconcile status polling failed ${consecutiveFailures} times in a row: ${e.message}", e
                    )
                }
                log.warn("Transient reconcile status poll failure ({}/3): {}", consecutiveFailures, e.message)
                continue
            }
            consecutiveFailures = 0

            when (statusBody["status"]?.toString()) {
                "COMPLETED" -> {
                    // An aborted-by-safety-brake sweep is COMPLETED with result.aborted=true —
                    // the caller surfaces the warning, same as the old synchronous response.
                    val resultMap = statusBody["result"] as? Map<*, *>
                    return ReconcileStaleResult(
                        rowsDeleted = (resultMap?.get("rowsDeleted") as? Number)?.toInt() ?: 0,
                        cutoff = resultMap?.get("cutoff")?.toString() ?: importStartedAt.toString(),
                        severities = (resultMap?.get("severities") as? List<*>)?.map { it.toString() }
                            ?: severities,
                        aborted = (resultMap?.get("aborted") as? Boolean) ?: false,
                        abortReason = resultMap?.get("abortReason")?.toString(),
                        dryRun = (resultMap?.get("dryRun") as? Boolean) ?: false,
                        wouldDelete = (resultMap?.get("wouldDelete") as? Number)?.toLong()
                    )
                }
                "FAILED" -> throw ReconcileFailedException(
                    "Reconcile job failed on backend: ${statusBody["errorMessage"] ?: "unknown error"}"
                )
                else -> { /* PENDING / RUNNING — keep polling */ }
            }
        }
    }
}

/**
 * Thrown by [VulnerabilityStorageService.reconcileStaleVulnerabilities] when the
 * sweep cannot complete. The CLI must propagate this as a non-zero exit code so
 * cron/operators know stale CrowdStrike vulnerability rows may still be present.
 */
class ReconcileFailedException(message: String, cause: Throwable? = null) : RuntimeException(message, cause)

/**
 * Result of a storage operation
 */
data class StorageResult(
    val stored: Int,
    val skipped: Int,
    val errors: List<String>,
    val assetsCreated: Int = 0,
    val message: String = ""
)

/**
 * Batch of vulnerabilities for a single server with metadata
 */
data class ServerVulnerabilityBatch(
    val hostname: String,
    val vulnerabilities: List<CrowdStrikeVulnerabilityDto>,
    val groups: String? = null,
    val cloudAccountId: String? = null,
    val cloudInstanceId: String? = null,
    val adDomain: String? = null,
    val osVersion: String? = null,
    val ip: String? = null
)

/**
 * Result of a batch storage operation
 */
data class BatchStorageResult(
    val serversProcessed: Int,
    val serversCreated: Int,
    val serversUpdated: Int,
    val vulnerabilitiesImported: Int,
    val vulnerabilitiesWithPatchDate: Int,
    val vulnerabilitiesSkipped: Int,
    val errors: List<String>,
    /**
     * Hostnames whose vulnerabilities were NOT persisted this run: a whole POST
     * chunk failed, or the backend reported the server's own import transaction
     * rolled back. These hosts still hold their previous rows un-refreshed, so
     * the caller MUST exclude them from the reconcile sweep's scope — sweeping
     * them deletes their rows with nothing reinserted.
     */
    val failedHostnames: List<String> = emptyList()
)

/**
 * Outcome of a `reconcile-stale` call. `null` returned by the caller means the
 * HTTP call itself failed; here the count is what the backend actually deleted.
 */
data class ReconcileStaleResult(
    val rowsDeleted: Int,
    val cutoff: String,
    val severities: List<String>,
    val aborted: Boolean = false,
    val abortReason: String? = null,
    /** True when the backend ran the sweep in report-only mode. */
    val dryRun: Boolean = false,
    /** Rows the sweep would have deleted (dry runs only). */
    val wouldDelete: Long? = null
)

