            serversProcessed = results.sumOf { it.serversProcessed },
            serversCreated = results.sumOf { it.serversCreated },
            serversUpdated = results.sumOf { it.serversUpdated },
            vulnerabilitiesImported = results.sumOf { it.vulnerabilitiesImported },
            vulnerabilitiesWithPatchDate = results.sumOf { it.vulnerabilitiesWithPatchDate },
            vulnerabilitiesSkipped = results.sumOf { it.vulnerabilitiesSkipped },
