    override fun queryVulnerabilities(hostname: String, config: FalconConfigDto): CrowdStrikeQueryResponse {
        require(hostname.isNotBlank()) { "Hostname cannot be blank" }

        log.info("Querying CrowdStrike for vulnerabilities: hostname={}", hostname)

        return try {
            // Authenticate
            val token = getAuthToken(config)

            // Get ALL device IDs for the hostname: a re-imaged/re-enrolled host has
            // several aids and its open vulnerabilities are spread across them, so
            // querying only the first aid under-reports (observed: 0 rows while a
            // sibling aid held thousands). Same per-device loop as
            // queryVulnerabilitiesByInstanceId — one dead aid must not sink the host.
            val deviceIds = getDeviceIdsByHostname(hostname, token)
            if (deviceIds.isEmpty()) {
                throw NotFoundException("Hostname not found in CrowdStrike: $hostname")
            }

            log.info("Hostname '{}' resolved to {} device id(s): {}", hostname, deviceIds.size, deviceIds)

            val vulnerabilityDtos = mutableListOf<CrowdStrikeVulnerabilityDto>()
            deviceIds.forEach { deviceId ->
                try {
                    // Query Spotlight API - pass hostname so it can be included in results
                    vulnerabilityDtos.addAll(querySpotlightApi(deviceId, hostname, token))
                } catch (e: Exception) {
                    log.warn("Failed to query vulnerabilities for device {} of hostname '{}': {}",
                        deviceId, hostname, e.message)
                }
            }
            // Spotlight vulnerability ids are unique per aid; dedupe by id is
            // belt-and-braces against overlapping resolutions.
            val merged = vulnerabilityDtos.distinctBy { it.id }

            log.info("Successfully queried CrowdStrike: hostname={}, devices={}, count={}",
                hostname, deviceIds.size, merged.size)

            CrowdStrikeQueryResponse(
                hostname = hostname,
                vulnerabilities = merged,
                totalCount = merged.size,
                deviceCount = deviceIds.size,
                queriedAt = LocalDateTime.now()
            )
        } catch (e: CrowdStrikeException) {
            hostnames.forEach { hostname ->
                try {
                    val response = queryVulnerabilities(hostname, config)
                    // Filter by severity and days open
                    val filtered = response.vulnerabilities.filter { vuln ->
                        val severityMatches = severity.split(",").any {
                            it.trim().equals(vuln.severity, ignoreCase = true)
                        }
                        // Parse daysOpen from string (e.g., "15 days" -> 15)
                        val daysOpenValue = vuln.daysOpen?.split(" ")?.firstOrNull()?.toIntOrNull() ?: 0
                        val daysOpenMatches = daysOpenValue >= minDaysOpen
                        severityMatches && daysOpenMatches
                    }
                    allVulnerabilities.addAll(filtered)
                    log.debug("Hostname '{}': found {} vulnerabilities ({} after filtering)",
                        hostname, response.vulnerabilities.size, filtered.size)
                } catch (e: NotFoundException) {
                    // Recorded, not just logged: the caller must be able to distinguish
                    // "unknown to Falcon" from "resolved but no matching rows".
                    notFoundHostnames.add(hostname)
                    log.warn("Hostname '{}' not found in CrowdStrike, skipping", hostname)
                } catch (e: Exception) {
                    log.error("Error querying hostname '{}'", hostname, e)
                    throw e
                }
                limit = limit,
                lastSeenDays = lastSeenDays
            )

            System.out.println("Found ${response.vulnerabilities.size} vulnerabilities across ${parsedDeviceType.displayName()}")

            val vulnerabilitiesByHostname = response.vulnerabilities.groupBy { it.hostname }

            // Per-host status: distinguish "unknown to Falcon" from "resolved, 0 matching
            // rows" — before, both collapsed into the same silent count=0/exit-0.
            val requestedHostnames = hostnames ?: emptyList()
            val notFound = response.notFoundHostnames.map { it.lowercase() }.toSet()
            requestedHostnames.forEach { requested ->
                val vulns = vulnerabilitiesByHostname.entries
                    .firstOrNull { it.key.equals(requested, ignoreCase = true) }?.value
                val status = when {
                    requested.lowercase() in notFound -> "not found in CrowdStrike"
                    vulns == null -> "resolved, 0 matching vulnerabilities"
                    else -> "${vulns.size} vulnerabilities"
                }
                System.out.println("  - $requested: $status")
            }
            if (requestedHostnames.isNotEmpty() && notFound.size >= requestedHostnames.size) {
                System.err.println("Error: none of the requested hostnames were found in CrowdStrike")
                return 1
            }

            if (response.vulnerabilities.isEmpty()) {
                System.out.println("No vulnerabilities found matching criteria")
                return 0
            }

            System.out.println("${parsedDeviceType.displayName().replaceFirstChar { it.uppercase() }} with vulnerabilities: ${vulnerabilitiesByHostname.size}")

            if (verbose) {
                vulnerabilitiesByHostname.forEach { (hostname, vulns) ->
                    System.out.println("  - $hostname: ${vulns.size} vulnerabilities")
                }
            }

            val hostsWithOverdue = vulnerabilitiesByHostname.count { (_, vulns) ->
                vulns.any { parseDaysOpenToInt(it.daysOpen) > overdueThreshold }
            }
            val totalHosts = vulnerabilitiesByHostname.size
            val hostsWithoutOverdue = totalHosts - hostsWithOverdue
            val overduePercent = hostsWithOverdue * 100.0 / totalHosts
            System.out.println("\n--- Vulnerability Age Summary (>$overdueThreshold days) ---")
            System.out.println("Servers with vulnerabilities older than $overdueThreshold days: $hostsWithOverdue of $totalHosts (${String.format("%.1f", overduePercent)}%)")
            System.out.println("Servers with no vulnerabilities older than $overdueThreshold days: $hostsWithoutOverdue of $totalHosts")

            if (dryRun) {
                System.out.println("\n[DRY-RUN MODE] Would import ${vulnerabilitiesByHostname.size} ${parsedDeviceType.displayName()} with ${response.vulnerabilities.size} vulnerabilities")
                return 0
            }

            if (!save) {
                System.out.println("\nQuery completed successfully. Use --save to import directly to database.")
                return 0
            }

            // Import via backend HTTP API
            System.out.println("\nImporting to database...")

            val serverBatches = vulnerabilitiesByHostname.map { (hostname, vulns) ->
                val firstVuln = vulns.firstOrNull()
                val latestCloudInstanceId = vulns
                    .filter { !it.cloudInstanceId.isNullOrBlank() }
                    .maxByOrNull { it.detectedAt ?: java.time.LocalDateTime.MIN }
                    ?.cloudInstanceId
                hostname to ServerVulnerabilityBatch(
                    hostname = hostname,
                    vulnerabilities = vulns,
                    groups = null,
                    cloudAccountId = firstVuln?.cloudAccountId,
                    cloudInstanceId = latestCloudInstanceId ?: firstVuln?.cloudInstanceId,
                    adDomain = firstVuln?.adDomain,
                    osVersion = null,
                    ip = vulns.resolveHostIp()
                )
            }.toMap()

            val systemsWithOverdueVulns = serverBatches.count { (_, batch) ->
                batch.vulnerabilities.any { parseDaysOpenToInt(it.daysOpen) > overdueThreshold }
            }

            val result = storageService.storeServerVulnerabilities(serverBatches, backendUrl = resolvedBackendUrl, authToken = authToken)
                serversCreated = 0,
                serversUpdated = 0,
                vulnerabilitiesImported = 0,
                vulnerabilitiesWithPatchDate = 0,
                vulnerabilitiesSkipped = 0,
                errors = emptyList()
            )
        }

        // Collapse Falcon's per-installation duplicates BEFORE any batching arithmetic, so
        // both the split thresholds and the posted payload count real findings. See
        // [dedupeByCveAndProduct] for why this cannot be left to the backend alone.
        val rawVulnCount = serverBatches.values.sumOf { it.vulnerabilities.size }
        val dedupedBatches = serverBatches.mapValues { (_, batch) ->
            batch.copy(vulnerabilities = dedupeByCveAndProduct(batch.vulnerabilities))
        }
        val dedupedVulnCount = dedupedBatches.values.sumOf { it.vulnerabilities.size }
        if (dedupedVulnCount < rawVulnCount) {
            log.info("Collapsed {} duplicate (CVE, product) row(s) across {} server(s) before send ({} -> {})",
                rawVulnCount - dedupedVulnCount, dedupedBatches.size, rawVulnCount, dedupedVulnCount)
        }

        val totalServers = dedupedBatches.size
        log.info("Storing vulnerabilities for {} servers via backend batch import API (batch size: {})", totalServers, batchSize)

        // Split servers into chunks to avoid 413 errors
        val serverChunks = dedupedBatches.entries.chunked(batchSize)
        val totalChunks = serverChunks.size

        log.info("Split into {} batches of up to {} servers each", totalChunks, batchSize)

        // Aggregate results across all batches (atomic to permit parallel POST)
        val totalServersProcessed = java.util.concurrent.atomic.AtomicInteger(0)
        val totalServersCreated = java.util.concurrent.atomic.AtomicInteger(0)
        val totalServersUpdated = java.util.concurrent.atomic.AtomicInteger(0)
        val totalVulnerabilitiesImported = java.util.concurrent.atomic.AtomicInteger(0)
        val totalVulnerabilitiesWithPatchDate = java.util.concurrent.atomic.AtomicInteger(0)
        val totalVulnerabilitiesSkipped = java.util.concurrent.atomic.AtomicInteger(0)
        val allErrors = java.util.concurrent.CopyOnWriteArrayList<String>()
        val allFailedHostnames = java.util.concurrent.CopyOnWriteArrayList<String>()

