        val queriedAids = queriedHosts.mapNotNull { normalizeAid(it.crowdStrikeAid) }.distinct()
        val identitiesByAid = if (queriedAids.isEmpty()) {
            emptyMap()
        } else {
            crowdStrikeAssetIdentityRepository.findByCrowdStrikeAidIn(queriedAids)
                .associateBy { it.crowdStrikeAid }
        }
        for (host in queriedHosts) {
            val identityAssetId = normalizeAid(host.crowdStrikeAid)
                ?.let(identitiesByAid::get)
                ?.asset
                ?.id
            if (identityAssetId != null) {
                ids.add(identityAssetId)
                continue
            }
            val instanceAssetId = host.instanceId?.trim()?.takeIf { it.isNotBlank() }
                ?.let(assetRepository::findByCloudInstanceIdIgnoreCase)
                ?.id
            if (instanceAssetId != null) {
                ids.add(instanceAssetId)
                continue
            }
            host.hostname?.trim()?.takeIf { it.isNotBlank() }?.let { hostname ->
                val shortName = hostname.substringBefore(".")
                for (asset in assetRepository.findPotentialCrowdStrikeMatches(shortName)) {
                    asset.id?.let { ids.add(it) }
                }
            }
        }
