/**
 * Covers the retry-on-transient-gateway-failure behavior added to the batch-import
 * path (`storeServerVulnerabilities` -> ... -> `sendBatchToBackend`) used by
 * `secman query servers --save`. Before this, a 502/503/504 or read-timeout from the
 * reverse proxy during a long CrowdStrike import silently dropped that sub-batch's
 * vulnerabilities with no retry (2026-07-21 incident).
 */
@DisplayName("VulnerabilityStorageService gateway retry")
class VulnerabilityStorageServiceTest {

    private val httpClient = mockk<HttpClient>()
    private val blockingClient = mockk<BlockingHttpClient>()

    private lateinit var service: VulnerabilityStorageService

    @BeforeEach
    fun setUp() {
        every { httpClient.toBlocking() } returns blockingClient
        // Fast backoff in tests (production default is 2000ms via secman.crowdstrike.retry-backoff-base-ms).
        service = VulnerabilityStorageService(httpClient, ObjectMapper(), maxVulnerabilitiesPerBatch = 50000, retryBackoffBaseMs = 1L)
    }

    private fun oneServerBatch(): Map<String, ServerVulnerabilityBatch> = mapOf(
        "server-1" to ServerVulnerabilityBatch(
            hostname = "server-1",
            vulnerabilities = listOf(
                CrowdStrikeVulnerabilityDto(
                    id = "vuln-1",
                    hostname = "server-1",
                    ip = "10.0.0.1",
                    cveId = "CVE-2026-0001",
                    severity = "High",
                    cvssScore = 7.5,
                    affectedProduct = "openssl",
                    daysOpen = "5 days",
                    detectedAt = LocalDateTime.now(),
                    status = "open",
                    hasException = false,
                    crowdStrikeAid = "aid-server-1"
                )
            )
        )
    )

    @Test
    fun `batch payload carries Falcon agent identities`() {
        val request = slot<HttpRequest<*>>()
        every { blockingClient.exchange(capture(request), Map::class.java) } returns
            HttpResponse.ok<Map<*, *>>(successBody())

        service.storeServerVulnerabilities(oneServerBatch())

        @Suppress("UNCHECKED_CAST")
        val payload = request.captured.body.get() as List<Map<String, Any?>>
        assertThat(payload.single()["crowdStrikeAids"]).isEqualTo(listOf("aid-server-1"))
    }

    private fun gatewayException(status: HttpStatus): HttpClientResponseException {
        val response = HttpResponse.status<Any>(status)
        return HttpClientResponseException(status.reason, response)
    }

    private fun successBody(): Map<String, Any> = mapOf(
        "serversProcessed" to 1,
        "serversCreated" to 0,
        "serversUpdated" to 1,
        "vulnerabilitiesImported" to 1,
        "vulnerabilitiesWithPatchDate" to 0,
        "vulnerabilitiesSkipped" to 0,
        "errors" to emptyList<String>()
    )

    @Test
    @DisplayName("retries once on 504 then succeeds")
    fun retriesOnceOn504ThenSucceeds() {
        var callCount = 0
        every { blockingClient.exchange(any<HttpRequest<*>>(), Map::class.java) } answers {
            callCount++
            if (callCount == 1) throw gatewayException(HttpStatus.GATEWAY_TIMEOUT)
            HttpResponse.ok<Map<*, *>>(successBody())
        }
