/**
 * Regression test for the CrowdStrike stale-vulnerability cleanup pipeline.
 *
 * Pins the user-reported scenario: a critical reported on day 1 must NOT
 * persist in the database once subsequent runs no longer report it (because
 * it has been remediated in production). Five behavioural cases nail down
 * the expected semantics of:
 *
 *  - Per-host transactional replace (empty payload still wipes).
 *  - Queried-host-scoped reconcile: a host that is queried again but remediated
 *    is swept, while a host that dropped out of the run's scope (not queried)
 *    is preserved — the ANTRELAY02 regression guard.
 *  - Source-based scoping (V213): CrowdStrike vulns on human-owned assets
 *    are still cleaned up.
 *  - Severity history (V214): a CRITICAL-only run still sweeps yesterday's
 *    HIGH because HIGH is in the historical union.
 *  - Cross-source isolation: XLSX-imported vulns are never swept by
 *    CrowdStrike reconcile.
 */
@DisplayName("CrowdStrike Stale Vulnerability Cleanup Integration Tests")
class CrowdStrikeStaleVulnerabilityIntegrationTest : BaseIntegrationTest() {

    @Inject
    lateinit var importService: CrowdStrikeVulnerabilityImportService

    @Inject
    lateinit var assetRepository: AssetRepository

    @Inject
    lateinit var vulnerabilityRepository: VulnerabilityRepository

    @Inject
    lateinit var severityHistoryRepository: CrowdStrikeSeverityHistoryRepository

    @Inject
    lateinit var entityManager: jakarta.persistence.EntityManager

    @Test
    fun `first seen projection groups duplicate assets preserves oldest fallback and nullable keys`() {
        val asset = assetRepository.save(Asset(name = uniqueHostname("anchors"), type = "SERVER", owner = "test"))
        val sibling = assetRepository.save(Asset(name = uniqueHostname("sibling"), type = "SERVER", owner = "test"))
        val outside = assetRepository.save(Asset(name = uniqueHostname("outside"), type = "SERVER", owner = "test"))
        val old = LocalDateTime.of(2026, 1, 1, 0, 0)
        fun row(target: Asset, cve: String?, product: String?, anchor: LocalDateTime?) {
            val saved = vulnerabilityRepository.save(Vulnerability(asset = target,
                vulnerabilityId = cve, vulnerableProductVersions = product, scanTimestamp = old.plusDays(2)))
            saved.firstSeenAt = anchor
            vulnerabilityRepository.update(saved)
        }
        row(asset, "CVE-2026-1234", "product", old.plusDays(1))
        row(sibling, "CVE-2026-1234", "product", old)
        row(outside, "CVE-2026-1234", "product", old.minusDays(10))
        row(asset, null, null, null)
        row(asset, "CVE-2026-1234", "Product", old.plusDays(3))
        entityManager.flush()
        entityManager.clear()
        val anchors = vulnerabilityRepository.findFirstSeenAnchors(listOf(asset.id!!, sibling.id!!))
        assertThat(anchors).hasSize(3)
        assertThat(anchors.single { it.vulnerableProductVersions == "product" }.firstSeenAt).isEqualTo(old)
        assertThat(anchors.single { it.vulnerableProductVersions == "Product" }.firstSeenAt).isEqualTo(old.plusDays(3))
        assertThat(anchors.single { it.vulnerabilityId == null }.firstSeenAt).isEqualTo(old.plusDays(2))
    }

    @Test
    fun `combined scope counts preserve timestamp severity source and asset boundaries`() {
        val cutoff = LocalDateTime.of(2026, 1, 1, 12, 0)
        val asset = assetRepository.save(Asset(name = uniqueHostname("counts"), type = "SERVER", owner = "test"))
        val outside = assetRepository.save(Asset(name = uniqueHostname("outside"), type = "SERVER", owner = "test"))
