        } ?: "host:${hostname?.trim()?.lowercase().orEmpty()}:${domain?.trim()?.lowercase().orEmpty()}"
    fun rowIdentity(row: CrowdStrikeVulnerabilityDto): String {
        val device = byAid[row.crowdStrikeAid]
