private fun resolveQueriedAssetIds(queriedHosts: List<QueriedHostDto>): List<Long> {
    val ids = LinkedHashSet<Long>()
    val excludedIds = mutableSetOf<Long>()
    val queriedAids = queriedHosts.mapNotNull { normalizeAid(it.crowdStrikeAid) }.distinct()
    val identitiesByAid = if (queriedAids.isEmpty()) {
        emptyMap()
    } else {
        crowdStrikeAssetIdentityRepository.findByCrowdStrikeAidIn(queriedAids)
            .associateBy { it.crowdStrikeAid }
    }
    for (host in queriedHosts) {
        val identityAsset = normalizeAid(host.crowdStrikeAid)?.let(identitiesByAid::get)?.asset
        val instance = host.instanceId?.trim()?.takeIf(String::isNotBlank)
        val instanceAsset = instance?.let(assetRepository::findByCloudInstanceIdIgnoreCase)
        if (identityAsset != null && instanceAsset != null && identityAsset.id != instanceAsset.id) {
            identityAsset.id?.let(excludedIds::add)
            instanceAsset.id?.let(excludedIds::add)
            log.warn("Reconcile excluded device with conflicting AID and instance identities")
            continue
        }
        val stableAsset = identityAsset ?: instanceAsset
        if (stableAsset != null) {
            if (matchesDeviceMetadata(stableAsset, instance, host.cloudAccountId, host.adDomain)) {
                stableAsset.id?.let(ids::add)
            } else {
                stableAsset.id?.let(excludedIds::add)
                log.warn("Reconcile excluded device with conflicting stored metadata")
            }
            continue
        }
        val hostname = host.hostname?.trim()?.takeIf(String::isNotBlank) ?: continue
        val candidates = assetRepository.findPotentialCrowdStrikeMatches(hostname.substringBefore("."))
        // A short-name match is only safe when it identifies one compatible asset.
        if (candidates.size == 1 && matchesHostname(candidates.single(), hostname) &&
            matchesDeviceMetadata(candidates.single(), instance, host.cloudAccountId, host.adDomain)) {
            candidates.single().id?.let(ids::add)
        } else if (candidates.isNotEmpty()) {
            excludedIds.addAll(candidates.mapNotNull { it.id })
            log.warn("Reconcile excluded ambiguous or conflicting hostname match: candidates={}", candidates.size)
        }
    }
    return ids.filterNot { it in excludedIds }
}

