            ?.trim()
            ?.takeIf(String::isNotBlank)
            ?.let(assetRepository::findByCloudInstanceIdIgnoreCase)
        val identityMatch = identityMatches.singleOrNull()
        if (identityMatch != null && instanceMatch != null && identityMatch.id != instanceMatch.id) {
            throw IllegalStateException("CrowdStrike agent identity conflicts with cloud instance identity")
        }

